// Payload may arrive as the WhatsApp Trigger output, the raw Meta envelope,
// or wrapped under .body. Try every plausible shape rather than assuming one.
const first = $input.first()?.json ?? {};
const candidates = [first, first.body, first.body?.entry?.[0]?.changes?.[0]?.value, first.entry?.[0]?.changes?.[0]?.value].filter(Boolean);

let value = null;
for (const c of candidates) {
  if (Array.isArray(c?.messages) && c.messages.length > 0) { value = c; break; }
}

// Delivery-status callbacks (sent / delivered / read) carry a `statuses` array
// and no `messages`. They are normal traffic, not errors - the trigger is
// configured with messageStatusUpdates: all. Report and stop.
if (!value) {
  const isStatus = candidates.some(function (c) { return Array.isArray(c?.statuses); });
  return [{ json: { parsed: false, reason: isStatus ? 'delivery status callback' : 'no messages array found', sender_e164: '', button_norm: '', top_level_keys: Object.keys(first).toString() } }];
}

const msg = value.messages[0];
const waId = msg.from ?? value.contacts?.[0]?.wa_id ?? '';

// Numbers are stored with a leading +; Meta returns them without one.
// Prepend to the INBOUND value - never wrap the DB column in a function,
// which would defeat the index on elders.whatsapp_number.
const senderE164 = waId ? (String(waId).charAt(0) === '+' ? String(waId) : '+' + String(waId)) : '';

// Quick-reply text arrives in two different shapes.
const rawButton = msg.button?.text ?? msg.interactive?.button_reply?.title ?? '';

// Never compare raw strings (Templates.md 3.2). Lowercase, strip apostrophes
// and punctuation, collapse whitespace. Yes, that's fine -> yes thats fine
const buttonNorm = String(rawButton).toLowerCase().replace(/[\u0027\u2018\u2019\u0060]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();

// parsed=true only when we have a real message AND a usable sender. Downstream
// nodes must not run without it: an empty queryReplacement makes n8n send NO
// parameters, and the query then fails with 'there is no parameter $1'.
const ok = senderE164.length > 1;

return [{ json: { parsed: ok, reason: ok ? 'message' : 'message with no sender', sender_e164: senderE164, wa_id_raw: String(waId), message_type: msg.type ?? 'unknown', wa_message_id: msg.id ?? '', button_text_raw: String(rawButton), button_norm: buttonNorm, text_body: msg.text?.body ?? '' } }];

const db = $input.first().json;
const parsed = $('Parse Inbound Message').first().json;

// Exact normalised forms of the approved welcome buttons (Templates.md 3.2).
const YES = 'yes thats fine';
const NO = 'no thank you';

let route = 'unhandled';

// Consent is only in play for a known, active elder who has neither confirmed
// nor declined. Everything else falls through untouched - no guessing (P3).
if (db.found === true && db.consent_confirmed === false && db.consent_declined === false) {
  if (parsed.button_norm === YES) { route = 'consent_yes'; }
  else if (parsed.button_norm === NO) { route = 'consent_no'; }
}

return [{ json: Object.assign({}, db, parsed, { route: route }) }];
